#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(2));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<int>> adj(n + 1);
    for (const vector<long long>& e : edges) {
        adj[e[0]].push_back((int)e[1]);
        adj[e[1]].push_back((int)e[0]);
    }
    const int INF = 1000000000;
    int best = INF;
    for (int s = 1; s <= n; s++) {
        vector<int> dist(n + 1, -1), parent(n + 1, 0);
        dist[s] = 0;
        vector<int> queue = {s};
        for (size_t i = 0; i < queue.size(); i++) {
            int u = queue[i];
            if (2 * dist[u] + 1 >= best) break;
            for (int v : adj[u]) {
                if (dist[v] < 0) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    queue.push_back(v);
                } else if (v != parent[u]) {
                    best = min(best, dist[u] + dist[v] + 1);
                }
            }
        }
    }
    cout << (best < INF ? best : -1) << "\n";

    return 0;
}

