import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][2];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int nodes = (int) n;
        int[] head = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            head[(int) edges[i][0] + 1]++;
            head[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= nodes; v++) head[v + 1] += head[v];
        int[] to = new int[2 * edges.length];
        int[] fill = new int[nodes + 2];
        for (int i = 0; i < edges.length; i++) {
            int a = (int) edges[i][0], b = (int) edges[i][1];
            to[head[a] + fill[a]] = b;
            fill[a]++;
            to[head[b] + fill[b]] = a;
            fill[b]++;
        }
        final int INF = 1000000000;
        int best = INF;
        int[] dist = new int[nodes + 1];
        int[] parent = new int[nodes + 1];
        int[] queue = new int[nodes + 1];
        for (int s = 1; s <= nodes; s++) {
            Arrays.fill(dist, -1);
            dist[s] = 0;
            parent[s] = 0;
            int qh = 0, qt = 0;
            queue[qt++] = s;
            while (qh < qt) {
                int u = queue[qh++];
                if (2 * dist[u] + 1 >= best) break;
                for (int k = head[u]; k < head[u + 1]; k++) {
                    int v = to[k];
                    if (dist[v] < 0) {
                        dist[v] = dist[u] + 1;
                        parent[v] = u;
                        queue[qt++] = v;
                    } else if (v != parent[u]) {
                        best = Math.min(best, dist[u] + dist[v] + 1);
                    }
                }
            }
        }
        System.out.println(best < INF ? best : -1);
    }
}
